INSERT INTO records(id,country,system,data,version,updated_at)
  SELECT 'CAN-mrl','CAN','mrl','{"id":"CAN-mrl","country":"CAN","system":"mrl","batches":[],"projects":[{"id":"CAN-LRPS","buyer":"CAN","supplier":"Lockheed Martin (미국 FMS)","stage":"contract","model":"M142 HIMARS","qty":26,"amount":2600000000,"currency":"CAD","decisionYear":2026,"contractYear":2026,"deliveryStart":2029,"deliveryEnd":2034,"covers":1,"asOf":"2026-10-23","est":["deliveryEnd"],"text":"LRPS(L) 장거리 정밀타격(지상) 사업: 2026년 1월 미국 정부와 FMS 협정으로 M142 HIMARS 26대 도입. 늦어도 2029년 인도 시작, 2030년 초기 운용능력, 2034년 완전 운용능력 목표. 사업 전체 비용 추정 26억 캐나다달러(금액은 사업 전체 기준). 미 국무부 FMS 승인 통보 25-76(17.5억 달러). 인도 완료 연도는 완전 운용능력 연도(2034) 기준 추정. 캐나다는 기존 다연장로켓이 없어 신규 전력 수요를 이 계약이 채움","src":["can_lrps_dnd","can_lrps_army","can_lrps_fr"]}],"src":["can_lrps_dnd","can_lrps_army","can_lrps_fr"]}',1,to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  WHERE EXISTS (SELECT 1 FROM countries WHERE id='CAN') AND EXISTS (SELECT 1 FROM systems WHERE id='mrl')
    AND NOT EXISTS (SELECT 1 FROM records WHERE country='CAN' AND system='mrl') AND NOT EXISTS (SELECT 1 FROM records WHERE id='CAN-mrl');
UPDATE records SET data=jsonb_set(data::jsonb,'{projects}',(CASE WHEN jsonb_typeof(data::jsonb->'projects')='array' THEN data::jsonb->'projects' ELSE '[]'::jsonb END) || jsonb_build_array('{"id":"CAN-LRPS","buyer":"CAN","supplier":"Lockheed Martin (미국 FMS)","stage":"contract","model":"M142 HIMARS","qty":26,"amount":2600000000,"currency":"CAD","decisionYear":2026,"contractYear":2026,"deliveryStart":2029,"deliveryEnd":2034,"covers":1,"asOf":"2026-10-23","est":["deliveryEnd"],"text":"LRPS(L) 장거리 정밀타격(지상) 사업: 2026년 1월 미국 정부와 FMS 협정으로 M142 HIMARS 26대 도입. 늦어도 2029년 인도 시작, 2030년 초기 운용능력, 2034년 완전 운용능력 목표. 사업 전체 비용 추정 26억 캐나다달러(금액은 사업 전체 기준). 미 국무부 FMS 승인 통보 25-76(17.5억 달러). 인도 완료 연도는 완전 운용능력 연도(2034) 기준 추정. 캐나다는 기존 다연장로켓이 없어 신규 전력 수요를 이 계약이 채움","src":["can_lrps_dnd","can_lrps_army","can_lrps_fr"]}'::jsonb))::text,
  version=version+1, updated_at=to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  WHERE country='CAN' AND system='mrl' AND NOT (COALESCE(data::jsonb->'projects','[]'::jsonb) @> '[{"id":"CAN-LRPS"}]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_lrps_dnd"]'::jsonb)::text WHERE country='CAN' AND system='mrl' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_lrps_dnd"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_lrps_army"]'::jsonb)::text WHERE country='CAN' AND system='mrl' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_lrps_army"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_lrps_fr"]'::jsonb)::text WHERE country='CAN' AND system='mrl' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_lrps_fr"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{projects}',(CASE WHEN jsonb_typeof(data::jsonb->'projects')='array' THEN data::jsonb->'projects' ELSE '[]'::jsonb END) || jsonb_build_array('{"id":"CAN-CPSP","buyer":"CAN","supplier":"TKMS","stage":"selected","model":"Type 212CD","qty":12,"decisionYear":2026,"contractYear":2027,"deliveryStart":2034,"covers":1,"reserve":"Hanwha Ocean","asOf":"2026-10-23","est":[],"text":"CPSP(캐나다 초계 잠수함 사업): 2026-07-06 TKMS(Type 212CD) 우선 공급자 선정, 한화오션은 예비 공급자. 최대 12척, 늦어도 2027년 말 계약, 2034년 첫 4척 인도 목표. Victoria급은 2030년대 중후반까지 운용. 2026년 10월 현재 계약 협상 중(2027년 서명 목표)","src":["can_cpsp_pm","can_cpsp_bg","can_cpsp_dia","can_cpsp_saltwire"]}'::jsonb))::text,
  version=version+1, updated_at=to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  WHERE country='CAN' AND system='ssk' AND NOT (COALESCE(data::jsonb->'projects','[]'::jsonb) @> '[{"id":"CAN-CPSP"}]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_cpsp_pm"]'::jsonb)::text WHERE country='CAN' AND system='ssk' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_cpsp_pm"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_cpsp_bg"]'::jsonb)::text WHERE country='CAN' AND system='ssk' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_cpsp_bg"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_cpsp_dia"]'::jsonb)::text WHERE country='CAN' AND system='ssk' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_cpsp_dia"]'::jsonb);
UPDATE records SET data=jsonb_set(data::jsonb,'{src}',(data::jsonb->'src') || '["can_cpsp_saltwire"]'::jsonb)::text WHERE country='CAN' AND system='ssk' AND jsonb_typeof(data::jsonb->'src')='array' AND NOT (data::jsonb->'src' @> '["can_cpsp_saltwire"]'::jsonb);
UPDATE metadata SET value=(CAST(value AS BIGINT)+1)::text WHERE key='revision' AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version=9);
INSERT INTO schema_migrations(version,applied_at) VALUES (9, to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
